-- ============ 6) 删除无效活动登记（event 为负且 game_event 里不存在；本次实测共 0 行）============
-- 回滚依据：本地备份表 game_event_creature_bak_dead_20260917。
DELETE FROM game_event_creature WHERE event < 0;

-- ============ 7) 刷怪组（spawn_group）成员与组 override 统一 300 秒 ============
-- 站长决定：不走 override 那套，全部按 300 秒。
--  ① 生物组(Type=0)成员里属于普通怪（rank0/有掉落/无脚本/NPC 旗标为空）而值<>300 的 62 个 entry（614 个刷点）→ 300
--  ② 所有仍带 RespawnOverride 且不是 300/300 的组 → 300/300（含 8001 Silithus Hive'Ashi Drone 600/600；矿脉 416 组本来就是 300/300）
