UPDATE spawn_group SET RespawnOverrideMin = 300, RespawnOverrideMax = 300 WHERE RespawnOverrideMin IS NOT NULL AND (RespawnOverrideMin <> 300 OR RespawnOverrideMax <> 300);

-- 漏网补齐：刷怪组成员里 min<>300 但 max=300 的行（例：300 Zzarc' Vul 的 3 个刷点 240/300）
UPDATE creature SET spawntimesecsmin = 300, spawntimesecsmax = 300 WHERE id = 300 AND map IN (0,1,530) AND (spawntimesecsmin <> 300 OR spawntimesecsmax <> 300);

-- ============ 8) 补充：被批次筛选漏掉的普通怪 entry（合并时发现，2026-09-17 深夜补）============
-- 来源：① 原「第 2 批」47 个刷点（dynguid 补偿档 120~360，本地当时已改 300，但合并成 071 时漏进列表）：
--        212,730,818,889,892,1251,2949,6846,16964
--       ② 站长点名 entry 中不满足 1)/7) 筛选条件、因而未被覆盖的 3 个（本地已 300，云端仍是原值）：
--        1756 暴风城皇家卫兵(430)、21195 驯养的地狱野猪(180)、22252 龙喉苦工(180)
-- 核对方式：把云端与本地整张 creature 表逐行比对（guid 相同者），差异行里凡 entry 不在 071 列表内的 = 110 行，
--           正好是上述 12 个 entry；补入本语句后云端残留缺口 = 0（实测）。
UPDATE creature SET spawntimesecsmin = 300, spawntimesecsmax = 300 WHERE id IN (212,730,818,889,892,1251,1756,2949,6846,16964,21195,22252) AND map IN (0,1,530) AND (spawntimesecsmin <> 300 OR spawntimesecsmax <> 300);
